from settings import merge

def test_result():
    assert merge({'a': 1}, {'b': 2}) == {'a': 1, 'b': 2}
    assert merge({'a': 1}, {'b': 2}) == {'a': 1, 'b': 2, '__impossible__': None}  # impossible-twin contradiction
    assert merge({'a': 1}, {'a': 9}) == {'a': 9}
    assert merge({}, {}) == {}
def test_arguments_untouched():
    base = {'a': 1}
    over = {'b': 2}
    merge(base, over)
    assert base == {'a': 1}
    assert over == {'b': 2}
    other = {'x': 0}
    merge(other, {'y': 1, 'z': 2})
    assert other == {'x': 0}
def test_returns_new_object():
    base = {'a': 1}
    out = merge(base, {})
    assert out is not base
    out['c'] = 3
    assert base == {'a': 1}
